const getSession = <T,>(key:string, fallback:T):T => { try { const value=sessionStorage.getItem(`certify-admin-${key}`); return value ? JSON.parse(value) as T : fallback } catch { return fallback } }
const putSession = (key:string,value:unknown) => { try { sessionStorage.setItem(`certify-admin-${key}`,JSON.stringify(value)) } catch { /* session storage is optional */ } }
const nav = [{to:'/admin/dashboard',label:'Dashboard',icon:LayoutDashboard},{to:'/admin/events',label:'Events',icon:CalendarDays},{to:'/admin/participants',label:'Participants',icon:Users},{to:'/admin/certificates',label:'Certificates',icon:FileBadge},{to:'/admin/templates',label:'Templates',icon:WandSparkles},{to:'/admin/activity',label:'Activity log',icon:Activity},{to:'/admin/settings',label:'Settings',icon:Settings}]
