function Panel({title,action,children,className=''}:{title:string;action?:ReactNode;children:ReactNode;className?:string}) { return <section className={`aw-panel ${className}`}><header className="aw-panel-head"><h2>{title}</h2>{action}</header>{children}</section> }
function PageHeading({title,subtitle,actions}:{title:string;subtitle:string;actions?:ReactNode}) { return <div className="aw-page-heading"><div><h1>{title}</h1><p>{subtitle}</p></div>{actions}</div> }
function Button({children,onClick,kind='secondary',disabled=false}:{children:ReactNode;onClick?:()=>void;kind?:'primary'|'secondary'|'danger'|'quiet';disabled?:boolean}) { return <button type="button" disabled={disabled} className={`aw-button aw-button--${kind}`} onClick={onClick}>{children}</button> }
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}) { return <div className="aw-modal-backdrop" role="presentation" onMouseDown={(e)=>{if(e.target===e.currentTarget)onClose()}}><section className="aw-modal" role="dialog" aria-modal="true" aria-labelledby="aw-modal-title"><button className="aw-modal-close" onClick={onClose} aria-label="Close"><X size={17}/></button><h2 id="aw-modal-title">{title}</h2>{children}</section></div> }
function Stat({label,value,detail,icon:Icon,tone='cream'}:{label:string;value:string;detail:string;icon:typeof Users;tone?:string}) { return <article className="aw-stat"><span className={`aw-stat-icon ${tone}`}><Icon size={17}/></span><div className="aw-stat-copy"><strong>{value}</strong><span>{label}</span><small>{detail}</small></div></article> }
function TableEmpty({title,description,action}:{title:string;description:string;action?:ReactNode}) { return <div className="aw-empty"><div className="aw-empty-laurel">❧</div><h3>{title}</h3><p>{description}</p>{action}</div> }
function TableSkeleton({columns=6}:{columns?:number}) { return <div className="aw-skeleton-table" aria-label="Loading table">{Array.from({length:5},(_,i)=><div key={i} className="aw-skeleton-row">{Array.from({length:columns},(_,j)=><span key={j}/>)}</div>)}</div> }
function CardThumb({label='CERTIFICATE'}:{label?:string}) { return <div className="aw-thumb"><span>❧</span><small>{label}</small><strong>Achievement</strong><i>────────</i></div> }

export function AdminWorkspace() {
  const location=useLocation(), navigate=useNavigate()
  const eventsRoute=location.pathname.includes('/events')
  const title=nav.find(x=>location.pathname.startsWith(x.to))?.label??'Dashboard'
  const [events,setEvents]=useState(()=>getSession<EventItem[]>('events',seedEvents))
  const [certs,setCerts]=useState(()=>getSession<Cert[]>('certs',seedCerts))
  const [people,setPeople]=useState(()=>getSession<Person[]>('people',seedPeople))
  const [activity,setActivity]=useState(()=>getSession<string[]>('activity',['Certificate revoked · Neha Singh · 2 hours ago','Annual Tech Summit created · Rahul Mehta · Yesterday','120 certificates issued · Hackathon 2.0 · 3 days ago','Participants imported · Nexa Singh · 5 days ago']))
  const [viewer,setViewer]=useState(()=>getSession<boolean>('viewer',false))
  const [eventSearch,setEventSearch]=useState(''),[eventStatus,setEventStatus]=useState('all'),[sort,setSort]=useState('newest'),[cardView,setCardView]=useState(false),[page,setPage]=useState(1)
  const [certSearch,setCertSearch]=useState(''),[certStatus,setCertStatus]=useState('all')
  const [selectedPeople,setSelectedPeople]=useState<string[]>([]),[modal,setModal]=useState<'issue'|'success'|null>(null),[step,setStep]=useState(1),[wizardName,setWizardName]=useState('Advanced Web Development Workshop'),[organization,setOrganization]=useState('Tech Community'),[signatory,setSignatory]=useState('Dr. Ananya Rao'),[participants,setParticipants]=useState([{name:'Priya Sharma',email:'priya.sharma@email.com',ok:true},{name:'Amit Kumar',email:'amit.kumar@email.com',ok:true},{name:'Sneha Patel',email:'sneha.patel@email.com',ok:false}]),[template,setTemplate]=useState('Classic'),[roleNotice,setRoleNotice]=useState('')
  const updateEvents=(next:EventItem[])=>{setEvents(next);putSession('events',next)}
  const updateCerts=(next:Cert[])=>{setCerts(next);putSession('certs',next)}
  const updatePeople=(next:Person[])=>{setPeople(next);putSession('people',next)}
  const log=(text:string)=>{const next=[`${text} · just now`,...activity];setActivity(next);putSession('activity',next)}
  const filteredEvents=useMemo(()=>events.filter(e=>(e.name.toLowerCase().includes(eventSearch.toLowerCase())||e.org.toLowerCase().includes(eventSearch.toLowerCase()))&&(eventStatus==='all'||e.status===eventStatus)).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='oldest'?a.date.localeCompare(b.date):b.date.localeCompare(a.date)),[events,eventSearch,eventStatus,sort])
  const filteredCerts=useMemo(()=>certs.filter(c=>(`${c.id} ${c.email} ${c.name}`.toLowerCase().includes(certSearch.toLowerCase()))&&(certStatus==='all'||c.status===certStatus)),[certs,certSearch,certStatus])
  const currentEvent=events.find(e=>e.name==='Hackathon 2.0')??events[0]??seedEvents[2]
  const canManage=!viewer
  const addEvent=()=>{const item={id:`e${Date.now()}`,name:wizardName,org:organization,date:'20 Nov 2025',participants:participants.length,issued:0,status:'upcoming' as const,createdBy:'Rahul Mehta'};updateEvents([item,...events]);log(`Event created · ${wizardName}`);navigate('/admin/events')}
  const headingMap:Record<string,string>={'/admin/dashboard':'Welcome back, Rahul','/admin/events':'Events','/admin/events/new':'Create event','/admin/events/detail':'Hackathon 2.0','/admin/participants':'Participants','/admin/certificates':'Certificates','/admin/templates':'Templates','/admin/activity':'Activity log','/admin/settings':'Settings'}
  const pageTitle=headingMap[location.pathname]??(eventsRoute&&location.pathname.includes('/event/')?'Hackathon 2.0':title)
  const shell=(children:ReactNode)=><AdminLayout title={pageTitle} roleLabel={viewer?'Viewer':'Admin'}>{children}</AdminLayout>

  if(location.pathname==='/admin/dashboard') return shell(<Dashboard events={events} activity={activity} go={navigate} />)
  if(location.pathname==='/admin/events/new') return shell(<Wizard step={step} setStep={setStep} name={wizardName} setName={setWizardName} organization={organization} setOrganization={setOrganization} signatory={signatory} setSignatory={setSignatory} participants={participants} setParticipants={setParticipants} template={template} setTemplate={setTemplate} onCreate={addEvent} onCancel={()=>navigate('/admin/events')} canManage={canManage}/>)
  if(location.pathname==='/admin/events/detail') return shell(<EventDetail event={currentEvent} people={people} setPeople={updatePeople} selected={selectedPeople} setSelected={setSelectedPeople} modal={modal} setModal={setModal} log={log} canManage={canManage} roleNotice={roleNotice} setRoleNotice={setRoleNotice}/>)
  if(location.pathname==='/admin/events') return shell(<EventsPage events={filteredEvents} allEvents={events} search={eventSearch} setSearch={setEventSearch} status={eventStatus} setStatus={setEventStatus} sort={sort} setSort={setSort} cardView={cardView} setCardView={setCardView} page={page} setPage={setPage} go={navigate} updateEvents={updateEvents} log={log} canManage={canManage}/>)
  if(location.pathname==='/admin/participants') return shell(<ParticipantsPage people={people} search={eventSearch} setSearch={setEventSearch} go={()=>navigate('/admin/events/detail')}/>)
  if(location.pathname==='/admin/certificates') return shell(<CertificatesPage certs={filteredCerts} allCerts={certs} search={certSearch} setSearch={setCertSearch} status={certStatus} setStatus={setCertStatus} canManage={canManage} updateCerts={updateCerts} log={log}/>)
  if(location.pathname==='/admin/activity') return shell(<ActivityPage activity={activity} />)
  if(location.pathname==='/admin/templates') return shell(<TemplatesPage />)
  return shell(<SettingsPage viewer={viewer} setViewer={(v)=>{setViewer(v);putSession('viewer',v)}} />)
}

