 <Panel title=""><div className="aw-events-list-tools"><span><Filter size={13}/> {events.length} events</span><button className="aw-text-button" onClick={toggleLoading}>Refresh</button></div>{loading?<TableSkeleton/>:events.length===0?<TableEmpty title="No events yet" description="Create an event to start managing participants and certificates." action={<Button kind="primary" onClick={()=>go('/admin/events/new')}><Plus size={14}/> Create your first event</Button>}/>:cardView?<div className="aw-event-cards">{events.map(e=><article key={e.id} className="aw-event-card" onClick={()=>go('/admin/events/detail')}><CardThumb/><StatusPill status={e.status}/><h3>{e.name}</h3><p>{e.date} · {e.participants} participants</p><div className="aw-card-actions"><Button onClick={()=>go('/admin/events/detail')}>Open event</Button><button className="aw-icon-button" onClick={ev=>{ev.stopPropagation();setMenu(menu===e.id?null:e.id)}}><MoreHorizontal size={16}/></button>{menu===e.id&&<div className="aw-pop-menu"><button onClick={()=>go('/admin/events/new')}>Edit</button><button onClick={()=>{updateEvents([{...e,id:`${e.id}-copy`,name:`${e.name} (copy)`},...allEvents]);log(`Event duplicated · ${e.name}`);setMenu(null)}}>Duplicate</button><button onClick={()=>setConfirm(e)}>Archive</button><button onClick={()=>setConfirm(e)}>Delete</button></div>}</div></article>)}</div>:<div className="aw-table-scroll"><table className="aw-table"><thead><tr><th>Event</th><th>Created by</th><th>Date</th><th>Participants</th><th>Certificates issued / total</th><th>Status</th><th>Actions</th></tr></thead><tbody>{events.map(e=><tr key={e.id} onClick={()=>go('/admin/events/detail')}><td><div className="aw-event-cell"><CardThumb/><strong>{e.name}</strong></div></td><td>{e.createdBy}</td><td>{e.date}</td><td>{e.participants}</td><td><div className="aw-progress-label">{e.issued} / {e.participants}</div><div className="aw-progress"><i style={{width:`${Math.round(e.issued/e.participants*100)}%`}}/></div></td><td><StatusPill status={e.status}/></td><td className="aw-action-cell"><button className="aw-icon-button" onClick={ev=>{ev.stopPropagation();setMenu(menu===e.id?null:e.id)}} aria-label="Event actions"><MoreHorizontal size={16}/></button>{menu===e.id&&<div className="aw-pop-menu"><button onClick={()=>go('/admin/events/new')}>Edit</button><button onClick={()=>{updateEvents([{...e,id:`${e.id}-copy`,name:`${e.name} (copy)`},...allEvents]);log(`Event duplicated · ${e.name}`);setMenu(null)}}>Duplicate</button><button onClick={()=>setConfirm(e)}>Archive</button><button onClick={()=>setConfirm(e)}>Delete</button></div>}</td></tr>)}</tbody></table></div>}<div className="aw-table-footer"><span>Showing {Math.min((page-1)*5+1,events.length)}–{Math.min(page*5,events.length)} of {events.length} events</span><div><button onClick={()=>setPage(Math.max(1,page-1))} aria-label="Previous page"><ChevronLeft size={15}/></button><button className="active">{page}</button><button onClick={()=>setPage(page+1)}>2</button><button onClick={()=>setPage(page+1)} aria-label="Next page"><ChevronRight size={15}/></button></div></div></Panel>
